/* Rehash after each mutation: rejection must be semantic, not stale digest. */
static void rehashed_invalid(void) {
    char saved[129];memcpy(saved,manifest.map_id,sizeof(saved));size_t size=manifest.serialized_size;
    CHECK(!sts_observation_manifest_digest(&config,&manifest));CHECK(!sts_observation_manifest_valid(&config,&manifest));
    memcpy(manifest.map_id,saved,sizeof(saved));manifest.serialized_size=size;
}
