static void metadata_bounds(void) {
#if defined(__linux__)
    /* Canonical map fits, but separately bounded expanded JSON cannot. */
    sts_observation_manifest m=manifest;
    m.decl_count=STS_OBS_DECL_LIMIT;
    m.declarations=calloc(m.decl_count,sizeof(*m.declarations));CHECK(m.declarations);
    char *names=malloc((size_t)(m.decl_count-2)*(STS_OBS_IDENTIFIER_LIMIT+1));CHECK(names);
    for(uint32_t i=0;i<m.decl_count-2;++i){
        char *name=names+(size_t)i*(STS_OBS_IDENTIFIER_LIMIT+1);
        memset(name,'x',STS_OBS_IDENTIFIER_LIMIT);name[STS_OBS_IDENTIFIER_LIMIT]=0;
        char suffix[16];snprintf(suffix,sizeof(suffix),"%08u",i);memcpy(name,suffix,8);
        m.declarations[i]=declarations[0];m.declarations[i].decl_id=i;m.declarations[i].ordinal_in_file=i;m.declarations[i].name=name;
    }
    /* Owner metadata for the first two sites is independently preserved. */
    strcpy(names,"helper");
    m.declarations[m.decl_count-2]=declarations[1];m.declarations[m.decl_count-1]=declarations[2];
    for(uint32_t i=m.decl_count-2;i<m.decl_count;++i){m.declarations[i].decl_id=i;m.declarations[i].ordinal_in_file=i;}
    sts_observation_test selected[2]={tests[0],tests[1]};selected[0].decl_id=m.decl_count-2;selected[1].decl_id=m.decl_count-1;m.tests=selected;
    CHECK(!sts_observation_manifest_digest(&config,&m));CHECK(m.serialized_size<STS_OBS_METADATA_LIMIT);CHECK(sts_observation_manifest_valid(&config,&m));
    sts_observation_run run={.image_fd=-1};CHECK(sts_observation_metadata_preflight(&run,&config,&m,error,sizeof(error))!=0);
    free(names);free(m.declarations);
#endif
}
