static pid_t fake_wait(pid_t pid,int *status,int options) {
    CHECK(pid==123 && options==0); ++waits;
    if (wait_mode==0 && waits<3) {errno=EINTR;return -1;}
    if (wait_mode==1) {errno=ECHILD;return -1;}
    *status=wait_mode==2 ? SIGTERM : 7<<8; return pid;
}
